   104  static int attrlookup(const wchar_t *string1, const MNEM_TAB *mtab)
   105  {
   106          int ix;
   107
   108          for (ix = 0; mtab[ix].mnem != NULL; ix++) {
   109                  if (attrcmp(string1, mtab[ix].mnem) == 0)
   110                          return mtab[ix].value;
   111          }
   112          return mtab[ix].value;
   113  }
